   <a class="skip-link" href="#support-form">Skip to form</a>

   <main id="main-content">
     <div class="shell">
       <section class="hero" aria-labelledby="support-heading">
         <div>
           <div class="eyebrow">Support</div>
           <h1 id="support-heading">Contact our team</h1>
           <p>
             Send a message to get help with your account, billing, or product questions.
             We’ll route it to the right support specialist.
           </p>
         </div>

         <div class="support-note" aria-label="Response expectations">
           <strong>What to expect</strong>
           <span>We reply by email and only use your phone number if we need to follow up quickly.</span>
         </div>
       </section>

       <section class="card" aria-labelledby="form-title">
         <h2 id="form-title">Send a message</h2>
         <form id="support-form" novalidate>
           <div class="form-field">
             <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
             <input
               id="full-name"
               name="fullName"
               type="text"
               autocomplete="name"
               required
               aria-describedby="full-name-error"
             >
             <p class="field-error" id="full-name-error" aria-live="polite"></p>
           </div>

           <div class="form-field">
             <label for="email-address">Email address <span class="required" aria-hidden="true">*</span></label>
             <input
               id="email-address"
               name="email"
               type="email"
               autocomplete="email"
               required
               aria-describedby="email-error"
             >
             <p class="field-error" id="email-error" aria-live="polite"></p>
           </div>

           <div class="form-field">
             <label for="phone-number">Phone number</label>
             <input
               id="phone-number"
               name="phone"
               type="tel"
               autocomplete="tel"
               inputmode="tel"
               aria-describedby="phone-help phone-error"
               placeholder="+1 (555) 123-4567"
             >
             <p class="field-hint" id="phone-help">Optional. Use digits with spaces, dashes, parentheses, or a leading plus sign. Example: +1 (555) 123-4567.</p>
             <p class="field-error" id="phone-error" aria-live="polite"></p>
           </div>

           <div class="actions">
             <button type="submit">Send message</button>
             <p class="status" id="form-status" aria-live="polite"></p>
           </div>
         </form>
       </section>
     </div>
   </main>

   <script>
     const form = document.getElementById('support-form');
     const status = document.getElementById('form-status');

     const fields = {
       fullName: {
         input: document.getElementById('full-name'),
         error: document.getElementById('full-name-error'),
         message: 'Error: Enter your full name.'
       },
       email: {
         input: document.getElementById('email-address'),
         error: document.getElementById('email-error'),
         message: 'Error: Enter a valid email address, like name@example.com.'
       },
       phone: {
         input: document.getElementById('phone-number'),
         error: document.getElementById('phone-error'),
         message: 'Error: Enter a phone number using digits, spaces, dashes, parentheses, or a leading plus sign.'
       }
     };

     function setFieldState(field, message) {
       field.error.textContent = message;
       field.input.setAttribute('aria-invalid', message ? 'true' : 'false');
     }

     function isValidPhone(value) {
       if (!value.trim()) {
         return true;
       }

       if (!/^[\d\s()+.-]+$/.test(value)) {
         return false;
       }

       const digits = value.replace(/\D/g, '');
       return digits.length >= 7 && digits.length <= 15;
     }

     function validateFullName() {
       const value = fields.fullName.input.value.trim();
       const message = value ? '' : fields.fullName.message;
       setFieldState(fields.fullName, message);
       return !message;
     }

     function validateEmail() {
       const input = fields.email.input;
       const value = input.value.trim();
       const message = value && input.validity.valid ? '' : fields.email.message;
       setFieldState(fields.email, message);
       return !message;
     }

     function validatePhone() {
       const value = fields.phone.input.value.trim();
       const message = isValidPhone(value) ? '' : fields.phone.message;
       setFieldState(fields.phone, message);
       return !message;
     }

     function validateAll() {
       const valid = [validateFullName(), validateEmail(), validatePhone()].every(Boolean);
       if (valid) {
         status.textContent = 'Message ready to send.';
         status.dataset.state = 'success';
       } else {
         status.textContent = 'Please fix the highlighted fields.';
         delete status.dataset.state;
       }
       return valid;
     }

     Object.values(fields).forEach(({ input }) => {
       input.addEventListener('blur', () => {
         if (input === fields.fullName.input) validateFullName();
         if (input === fields.email.input) validateEmail();
         if (input === fields.phone.input) validatePhone();
       });

       input.addEventListener('input', () => {
         if (input === fields.fullName.input) validateFullName();
         if (input === fields.email.input) validateEmail();
         if (input === fields.phone.input) validatePhone();
       });
     });

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       const valid = validateAll();
       if (!valid) {
         const firstInvalid = [fields.fullName, fields.email, fields.phone]
           .find(({ input }) => input.getAttribute('aria-invalid') === 'true');
         firstInvalid.input.focus();
         return;
       }

       status.textContent = 'Thanks — your message is ready to send.';
       status.dataset.state = 'success';
       form.reset();
       Object.values(fields).forEach((field) => setFieldState(field, ''));
     });
   </script>
