    }

    html {
      scroll-behavior: smooth;
    }

    body {
      margin: 0;
      font: 16px/1.5 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top, rgba(36, 87, 214, 0.12), transparent 32%),
        var(--bg);
    }

    a {
      color: inherit;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      padding: 0.75rem 1rem;
      border-radius: 999px;
      background: var(--panel);
      color: var(--text);
      box-shadow: var(--shadow);
      transform: translateY(-180%);
      transition: transform 0.2s ease;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 3px solid var(--primary);
      outline-offset: 2px;
    }

    main {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 4rem 1.25rem;
    }

    .shell {
      width: min(100%, 980px);
      display: grid;
      grid-template-columns: 1.05fr 1fr;
      gap: 1.5rem;
      align-items: stretch;
    }

    .hero,
    .card {
      border: 1px solid rgba(174, 189, 211, 0.7);
      border-radius: var(--radius);
      background: rgba(255, 255, 255, 0.85);
      backdrop-filter: blur(14px);
      box-shadow: var(--shadow);
    }

    .hero {
      padding: 2rem;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      gap: 2rem;
      background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.95), rgba(248, 250, 252, 0.9));
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      color: var(--primary);
      font-weight: 700;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      font-size: 0.8rem;
    }

    h1 {
      margin: 0.75rem 0 0;
      font-size: clamp(2rem, 4vw, 3.4rem);
      line-height: 1.05;
      letter-spacing: -0.04em;
      max-width: 10ch;
    }

    .hero p {
      margin: 1rem 0 0;
      max-width: 34rem;
      color: var(--muted);
      font-size: 1.02rem;
    }

    .card {
      padding: 1.5rem;
      background: var(--panel);
    }

    form {
      display: grid;
      gap: 1rem;
    }

    .form-field {
      display: grid;
      gap: 0.45rem;
    }

    label {
      font-weight: 600;
      color: var(--text);
    }

    .required {
      color: var(--error);
      margin-left: 0.15rem;
    }

    .field-hint {
      margin: 0;
      color: var(--muted);
      font-size: 0.92rem;
    }

    input {
      width: 100%;
      border: 1px solid var(--border);
      border-radius: 14px;
      background: var(--panel-2);
      color: var(--text);
      padding: 0.95rem 1rem;
      font: inherit;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease;
    }

    input::placeholder {
      color: #8a97ab;
    }

    input:hover {
      border-color: var(--border-strong);
    }

    input:focus {
      outline: none;
      border-color: var(--primary);
      box-shadow: 0 0 0 4px rgba(36, 87, 214, 0.14);
      background: #fff;
    }

    input[aria-invalid="true"] {
      border-color: var(--error);
      background: var(--error-bg);
    }

    .field-error {
      margin: 0;
      min-height: 1.25em;
      color: var(--error);
      font-size: 0.92rem;
      font-weight: 600;
    }

    .field-error:empty {
      display: block;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.85rem;
      align-items: center;
      margin-top: 0.25rem;
    }

    button {
      border: 0;
      border-radius: 999px;
      padding: 0.95rem 1.35rem;
      background: var(--primary);
      color: #fff;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      box-shadow: 0 14px 28px rgba(36, 87, 214, 0.24);
      transition: transform 0.15s ease, background-color 0.15s ease, box-shadow 0.15s ease;
    }

    button:hover {
      background: var(--primary-hover);
      transform: translateY(-1px);
      box-shadow: 0 16px 32px rgba(36, 87, 214, 0.28);
    }

    button:focus-visible {
      outline: 3px solid #0f172a;
      outline-offset: 3px;
    }

    .status {
      margin: 0;
      color: var(--muted);
      font-size: 0.92rem;
      min-height: 1.4em;
    }

    .status[data-state="success"] {
      color: #067647;
    }

    .support-note {
      display: grid;
      gap: 0.85rem;
      padding: 1rem 1.1rem;
      border-radius: 18px;
      background: rgba(36, 87, 214, 0.06);
      color: var(--muted);
    }

    .support-note strong {
      color: var(--text);
    }

